-- ═══════════════════════════════════════════════════════════════════════════
-- Customer Shopping Behavior Analysis — SQL Queries
-- Database: PostgreSQL  (compatible with MySQL / SQL Server with minor tweaks)
-- Table   : customer
-- Author  : Ankit Kumar (github.com/hrts51)
-- ═══════════════════════════════════════════════════════════════════════════

-- ─────────────────────────────────────────────────────────────────────────────
-- SECTION 1: REVENUE ANALYSIS
-- ─────────────────────────────────────────────────────────────────────────────

-- Q1. What is the total revenue generated by male vs. female customers?
SELECT
    gender,
    COUNT(customer_id)                     AS total_customers,
    SUM(purchase_amount)                   AS total_revenue,
    ROUND(AVG(purchase_amount)::NUMERIC, 2) AS avg_spend
FROM customer
GROUP BY gender
ORDER BY total_revenue DESC;


-- Q2. Which customers used a discount but still spent more than the average?
SELECT
    customer_id,
    purchase_amount,
    ROUND(purchase_amount - (SELECT AVG(purchase_amount) FROM customer), 2) AS above_avg_by
FROM customer
WHERE discount_applied = 'Yes'
  AND purchase_amount >= (SELECT AVG(purchase_amount) FROM customer)
ORDER BY purchase_amount DESC;


-- Q3. What is the revenue contribution of each age group?
SELECT
    age_group,
    COUNT(customer_id)                      AS total_customers,
    SUM(purchase_amount)                    AS total_revenue,
    ROUND(AVG(purchase_amount)::NUMERIC, 2) AS avg_spend,
    ROUND(100.0 * SUM(purchase_amount) / SUM(SUM(purchase_amount)) OVER (), 2) AS revenue_pct
FROM customer
GROUP BY age_group
ORDER BY total_revenue DESC;


-- Q4. Compare average purchase amounts between Standard and Express shipping.
SELECT
    shipping_type,
    COUNT(customer_id)                      AS order_count,
    ROUND(AVG(purchase_amount)::NUMERIC, 2) AS avg_spend,
    SUM(purchase_amount)                    AS total_revenue
FROM customer
WHERE shipping_type IN ('Standard', 'Express')
GROUP BY shipping_type
ORDER BY avg_spend DESC;


-- ─────────────────────────────────────────────────────────────────────────────
-- SECTION 2: PRODUCT ANALYSIS
-- ─────────────────────────────────────────────────────────────────────────────

-- Q5. Top 5 products with the highest average review rating.
SELECT
    item_purchased,
    COUNT(customer_id)                       AS total_purchases,
    ROUND(AVG(review_rating)::NUMERIC, 2)    AS avg_rating
FROM customer
GROUP BY item_purchased
ORDER BY avg_rating DESC
LIMIT 5;


-- Q6. Which 5 products have the highest percentage of discounted purchases?
SELECT
    item_purchased,
    COUNT(customer_id)                                                                   AS total_orders,
    SUM(CASE WHEN discount_applied = 'Yes' THEN 1 ELSE 0 END)                           AS discounted_orders,
    ROUND(100.0 * SUM(CASE WHEN discount_applied = 'Yes' THEN 1 ELSE 0 END) / COUNT(*), 2) AS discount_rate_pct
FROM customer
GROUP BY item_purchased
ORDER BY discount_rate_pct DESC
LIMIT 5;


-- Q7. Top 3 most purchased products within each category.
WITH item_counts AS (
    SELECT
        category,
        item_purchased,
        COUNT(customer_id)                                                        AS total_orders,
        ROW_NUMBER() OVER (PARTITION BY category ORDER BY COUNT(customer_id) DESC) AS item_rank
    FROM customer
    GROUP BY category, item_purchased
)
SELECT
    item_rank,
    category,
    item_purchased,
    total_orders
FROM item_counts
WHERE item_rank <= 3
ORDER BY category, item_rank;


-- ─────────────────────────────────────────────────────────────────────────────
-- SECTION 3: CUSTOMER SEGMENTATION & LOYALTY
-- ─────────────────────────────────────────────────────────────────────────────

-- Q8. Segment customers by loyalty tier (New / Returning / Loyal).
WITH loyalty AS (
    SELECT
        customer_id,
        previous_purchases,
        CASE
            WHEN previous_purchases = 1          THEN 'New'
            WHEN previous_purchases BETWEEN 2 AND 10 THEN 'Returning'
            ELSE 'Loyal'
        END AS loyalty_tier
    FROM customer
)
SELECT
    loyalty_tier,
    COUNT(*)                                AS customer_count,
    ROUND(AVG(c.purchase_amount)::NUMERIC, 2) AS avg_spend
FROM loyalty l
JOIN customer c USING (customer_id)
GROUP BY loyalty_tier
ORDER BY
    CASE loyalty_tier
        WHEN 'New'       THEN 1
        WHEN 'Returning' THEN 2
        ELSE 3
    END;


-- Q9. Do subscribed customers spend more?
SELECT
    subscription_status,
    COUNT(customer_id)                      AS total_customers,
    ROUND(AVG(purchase_amount)::NUMERIC, 2) AS avg_spend,
    ROUND(SUM(purchase_amount)::NUMERIC, 2) AS total_revenue
FROM customer
GROUP BY subscription_status
ORDER BY total_revenue DESC;


-- Q10. Are repeat buyers (> 5 purchases) more likely to subscribe?
SELECT
    subscription_status,
    COUNT(customer_id)                           AS repeat_buyer_count,
    ROUND(100.0 * COUNT(customer_id) /
        SUM(COUNT(customer_id)) OVER (), 2)       AS pct_of_repeat_buyers
FROM customer
WHERE previous_purchases > 5
GROUP BY subscription_status;


-- ─────────────────────────────────────────────────────────────────────────────
-- SECTION 4: ADVANCED ANALYTICS (NEW)
-- ─────────────────────────────────────────────────────────────────────────────

-- Q11. Running total of revenue ordered by purchase amount (cumulative distribution).
SELECT
    customer_id,
    purchase_amount,
    SUM(purchase_amount) OVER (ORDER BY purchase_amount ROWS BETWEEN UNBOUNDED PRECEDING AND CURRENT ROW) AS running_total,
    ROUND(100.0 * RANK() OVER (ORDER BY purchase_amount) / COUNT(*) OVER (), 2)                           AS percentile_rank
FROM customer
ORDER BY purchase_amount DESC
LIMIT 20;


-- Q12. Top 5 US states by total revenue.
SELECT
    location                                AS state,
    COUNT(customer_id)                      AS total_orders,
    SUM(purchase_amount)                    AS total_revenue,
    ROUND(AVG(purchase_amount)::NUMERIC, 2) AS avg_spend
FROM customer
GROUP BY location
ORDER BY total_revenue DESC
LIMIT 5;


-- Q13. Which payment method generates the highest average spend per transaction?
SELECT
    payment_method,
    COUNT(customer_id)                      AS transaction_count,
    ROUND(AVG(purchase_amount)::NUMERIC, 2) AS avg_spend,
    SUM(purchase_amount)                    AS total_revenue
FROM customer
GROUP BY payment_method
ORDER BY avg_spend DESC;


-- Q14. Season × Category revenue cross-tab (pivot-style using conditional aggregation).
SELECT
    category,
    SUM(CASE WHEN season = 'Spring' THEN purchase_amount ELSE 0 END) AS spring_revenue,
    SUM(CASE WHEN season = 'Summer' THEN purchase_amount ELSE 0 END) AS summer_revenue,
    SUM(CASE WHEN season = 'Fall'   THEN purchase_amount ELSE 0 END) AS fall_revenue,
    SUM(CASE WHEN season = 'Winter' THEN purchase_amount ELSE 0 END) AS winter_revenue,
    SUM(purchase_amount)                                               AS total_revenue
FROM customer
GROUP BY category
ORDER BY total_revenue DESC;


-- Q15. RFM-style customer scoring using existing columns.
--      Frequency proxy = purchase_frequency_days (lower = better)
--      Monetary        = purchase_amount
--      Loyalty         = previous_purchases
WITH rfm_scores AS (
    SELECT
        customer_id,
        purchase_frequency_days,
        purchase_amount,
        previous_purchases,
        NTILE(5) OVER (ORDER BY purchase_frequency_days DESC) AS r_score, -- lower days = higher score
        NTILE(5) OVER (ORDER BY previous_purchases)            AS f_score,
        NTILE(5) OVER (ORDER BY purchase_amount)               AS m_score
    FROM customer
),
rfm_total AS (
    SELECT *,
        r_score + f_score + m_score AS rfm_total_score
    FROM rfm_scores
)
SELECT
    CASE
        WHEN rfm_total_score >= 13 THEN 'Champions'
        WHEN rfm_total_score >= 10 THEN 'Loyal Customers'
        WHEN rfm_total_score >=  7 THEN 'Potential Loyalists'
        WHEN rfm_total_score >=  5 THEN 'At Risk'
        ELSE                            'Lost'
    END                                      AS rfm_segment,
    COUNT(*)                                 AS customer_count,
    ROUND(AVG(purchase_amount)::NUMERIC, 2)  AS avg_spend,
    ROUND(AVG(previous_purchases)::NUMERIC, 1) AS avg_prev_purchases
FROM rfm_total
GROUP BY rfm_segment
ORDER BY avg_spend DESC;
